import sys
from collections import deque

def bfs(capacity, source, sink, parent):
    visited = [False] * len(capacity)
    queue = deque([source])
    visited[source] = True
    while queue:
        u = queue.popleft()
        for v in range(len(capacity)):
            if not visited[v] and capacity[u][v] > 0:
                queue.append(v)
                visited[v] = True
                parent[v] = u
                if v == sink:
                    return True
    return False

def max_flow(capacity, source, sink):
    parent = [-1] * len(capacity)
    flow = 0
    while bfs(capacity, source, sink, parent):
        path_flow = float('Inf')
        s = sink
        while s != source:
            path_flow = min(path_flow, capacity[parent[s]][s])
            s = parent[s]
        v = sink
        while v != source:
            u = parent[v]
            capacity[u][v] -= path_flow
            capacity[v][u] += path_flow
            v = parent[v]
        flow += path_flow
    return flow

def max_flow_with_increase(capacity, n, k):
    original_capacity = [row[:] for row in capacity]
    max_increase = [[0] * n for _ in range(n)]
    queue = deque([(0, 1)])
    while queue:
        cost, u = queue.popleft()
        for v in range(n):
            if capacity[u][v] > 0 and max_increase[u][v] == 0:
                new_cost = cost + capacity[u][v]
                if new_cost <= k:
                    max_increase[u][v] = new_cost
                    queue.append((new_cost, v))
    for u in range(n):
        for v in range(n):
            if max_increase[u][v] > 0:
                capacity[u][v] += k - max_increase[u][v] + 1
    return max_flow(capacity, 0, n - 1)

